<main class="container">
<div class="page-heading"><div><h1>Tenants and Tenancies</h1><p>Register tenants, assign vacant units, record lease periods and manage caution fees.</p></div><a class="button-link" href="<?= e(base_url('?page=units')) ?>">Manage units</a></div>
<?php if ($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?>
<section class="panel"><h2><?= $edit ? 'Edit tenant and active tenancy' : 'Register a tenant' ?></h2>
<?php if (!$availableUnits): ?><p>No vacant units are available. Register a property and a vacant unit before adding a tenant. <a href="<?= e(base_url('?page=units')) ?>">Manage units</a>.</p><?php else: ?>
<form method="post" action="<?= e(base_url('?page=tenants' . ($edit ? '&edit=' . (int)$edit['tenantId'] : ''))) ?>">
<?= csrf_field() ?><input type="hidden" name="action" value="save">
<?php if ($edit): ?><input type="hidden" name="tenantId" value="<?= (int)$edit['tenantId'] ?>"><?php endif; ?>
<label for="fullName">Tenant full name</label><input id="fullName" name="fullName" maxlength="100" required value="<?= e($edit['fullName'] ?? '') ?>" placeholder="e.g. Amina Yusuf">
<label for="phone">Phone number</label><input id="phone" name="phone" type="tel" maxlength="20" required value="<?= e($edit['phone'] ?? '') ?>" placeholder="e.g. 08012345678">
<label for="email">Email address (optional)</label><input id="email" name="email" type="email" maxlength="100" value="<?= e($edit['email'] ?? '') ?>" placeholder="e.g. tenant@example.com">
<label for="unitId">Rental unit</label><select id="unitId" name="unitId" required><option value="">Select a vacant unit</option><?php foreach ($availableUnits as $unit): ?><option value="<?= (int)$unit['unitId'] ?>" <?= (int)($edit['unitId'] ?? 0) === (int)$unit['unitId'] ? 'selected' : '' ?>><?= e($unit['propertyName'] . ' — ' . $unit['unitNumber'] . ' (₦' . number_format((float)$unit['annualRent'], 2) . '/year)') ?></option><?php endforeach; ?></select>
<div class="form-grid"><div><label for="leaseStart">Lease start date</label><input id="leaseStart" name="leaseStart" type="date" required value="<?= e($edit['leaseStart'] ?? '') ?>"></div><div><label for="leaseEnd">Lease end date</label><input id="leaseEnd" name="leaseEnd" type="date" required value="<?= e($edit['leaseEnd'] ?? '') ?>"></div></div>
<label for="cautionFee">Caution fee / security deposit (₦)</label><input id="cautionFee" name="cautionFee" type="number" min="0" step="0.01" required value="<?= e(isset($edit['cautionFee']) ? (string)$edit['cautionFee'] : '0') ?>" placeholder="e.g. 100000">
<button type="submit"><?= $edit ? 'Save tenant changes' : 'Register tenant and create tenancy' ?></button><?php if ($edit): ?> <a class="button-link" href="<?= e(base_url('?page=tenants')) ?>">Cancel</a><?php endif; ?>
</form><?php endif; ?></section>
<section class="panel"><h2>Registered tenants and tenancies</h2><?php if (!$tenants): ?><p>No tenants have been registered yet. Use the form above to register the first tenant.</p><?php else: ?>
<div class="table-wrap"><table><thead><tr><th>Tenant</th><th>Phone / Email</th><th>Property / Unit</th><th>Lease period</th><th>Caution fee</th><th>Status / Actions</th></tr></thead><tbody>
<?php foreach ($tenants as $tenant): ?><tr><td><?= e($tenant['fullName']) ?></td><td><?= e($tenant['phone']) ?><br><?= e($tenant['email'] ?? '—') ?></td><td><?= e($tenant['propertyName'] ?? '—') ?><br><?= e($tenant['unitNumber'] ?? 'No active unit') ?></td><td><?= e($tenant['leaseStart']) ?> to <?= e($tenant['leaseEnd']) ?></td><td>₦<?= number_format((float)$tenant['cautionFee'], 2) ?></td><td><?php if ($tenant['tenancyStatus'] === 'active'): ?><span class="status occupied">Active</span><div class="actions"><a href="<?= e(base_url('?page=tenants&edit=' . (int)$tenant['tenantId'])) ?>">Edit</a><form method="post" action="<?= e(base_url('?page=tenants')) ?>" onsubmit="return confirm('End this tenancy? The unit will become vacant. Historical records will be retained.');"><?= csrf_field() ?><input type="hidden" name="action" value="end"><input type="hidden" name="tenantId" value="<?= (int)$tenant['tenantId'] ?>"><button class="button-danger" type="submit">End tenancy</button></form></div><?php else: ?><span class="status vacant">No active tenancy</span><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section></main>
